	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "question_generation_claims_key_hex" CHECK (generation_key ~ '^[0-9a-f]{64}$'),
	CONSTRAINT "question_generation_claims_attempt_positive" CHECK (attempt >= 1),
	CONSTRAINT "question_generation_claims_holder_bounded" CHECK (char_length(holder) BETWEEN 1 AND 200),
